# frozen_string_literal: true
require 'json'
require 'cgi'
require 'date'
require 'uri'
require_relative 'guide_ui'
module FishingGuide
  DATA=JSON.parse(File.read(File.expand_path('../_data/fishing-guide.json',__dir__)))
  module_function
  def h(s);CGI.escapeHTML(s.to_s);end
  def source(id,label=nil)
    r=DATA.fetch('sources').find{|x|x['id']==id} || raise(id)
    %(<a href="#{h(r['url'])}" rel="noopener">#{h(label||r['title'])}#{GuideUI.icon('external')}</a>)
  end
  def photo(id,hero:false)
    p=DATA['photos'].find{|x|x['id']==id} || raise(id)
    %(<figure class="fish-photo #{hero ? 'fish-hero-photo' : ''}"><img src="#{p['src']}" srcset="#{p['srcset']}" sizes="#{hero ? '(max-width: 800px) 100vw, 60vw' : '(max-width: 600px) 100vw, 33vw'}" width="#{p['width']}" height="#{p['height']}" alt="#{h(p['alt'])}" #{hero ? 'fetchpriority="high"' : 'loading="lazy"'} decoding="async"><figcaption>#{h(p['title'])} · #{h(p['author'])} · <a href="/pilsetas-un-fotografijas/#copes-foto-#{id}">#{h(p['license']=='Public domain' ? 'Publiskais īpašums' : p['license'])}</a></figcaption></figure>)
  end
  def fmt(md);m,d=md.split('-');"#{d.to_i}.#{m.to_i}.";end
  def timeline(c)
    start=Date.parse("2027-#{c['start']}");finish=Date.parse("2027-#{c['end']}")+1
    left=(start.yday-1)*100.0/365;width=(finish.yday-start.yday)*100.0/365
    %(<div class="fish-year-track" aria-label="#{fmt(c['start'])}–#{fmt(c['end'])}: #{h(c['kind'])}"><span style="left:#{left.round(4)}%;width:#{width.round(4)}%"></span></div>)
  end
  def page
    rows=DATA['closures'].map{|c|%(<tr><th scope="row">#{h(c['title'])}<small>#{h(c['kind'])}</small></th><td>#{timeline(c)}</td><td><b>#{fmt(c['start'])}–#{fmt(c['end'])}</b><small>#{h(c['scope'])}</small></td></tr>)}.join
    cards=DATA['fish'].map do |f|
      %(<article class="fish-species-card" id="zivs-#{f['id']}">#{photo(f['id'])}<div class="fish-species-body"><header><div><h3>#{h(f['name'])}</h3><i>#{h(f['latin'])}</i></div><span class="fish-size"><b>#{f['minLength'] || '—'}</b>#{f['minLength'] ? 'cm minimums' : 'Skati noteikumus'}</span></header><p>#{h(f['identity'])}</p><dl><div><dt>Paturēšanas liegums</dt><dd>#{f['start'] ? "#{fmt(f['start'])}–#{fmt(f['end'])}" : 'Nav atsevišķa valsts sugas lieguma'}</dd></div><div><dt>Pamatlimits vienai personai</dt><dd>#{h(f['limit'])}</dd></div></dl><details><summary>Sezona un vietējie izņēmumi</summary><p>#{h(f['note'])}</p>#{source('rules','Pārbaudīt 16., 18. un 23. punktu')}</details><button type="button" class="fish-text-button" data-fish-select="#{f['id']}">Pārbaudīt datumu šai sugai #{GuideUI.icon('arrow')}</button></div></article>)
    end.join
    waters=DATA['waters'].map do |w|
      art=w['photo'] ? photo(w['photo']) : %(<div class="fish-water-heading"><span>#{h(w['region'])}</span><strong>#{h(w['name'])}</strong><span>Licence · piekļuve · vietējais nolikums</span></div>)
      map='https://www.google.com/maps/search/?api=1&query='+URI.encode_www_form_component(w['query'])
      %(<article class="fish-water-card" id="udens-#{w['id']}">#{art}<div class="fish-water-body"><header><span class="fish-kicker">#{h(w['region'])}</span><h3>#{h(w['name'])}</h3></header><p class="fish-water-season">#{GuideUI.icon('calendar')}#{h(w['opening'])}</p><dl><div><dt>Kas vajadzīgs</dt><dd>#{h(w['licence'])}</dd></div><div><dt>Kur sākt braucienu</dt><dd>#{h(w['access'])}</dd></div></dl><p>#{h(w['detail'])}</p><div class="fish-place-actions">#{source(w['sourceId'],'Licence un informācija')}<a href="#{map}" rel="noopener">Atvērt vietu kartē#{GuideUI.icon('external')}</a></div><details><summary>Piekļuve un vietējie noteikumi</summary>#{source(w['accessId'],'Piekļuve un kontakti')}#{source(w['lawId'],'Lasīt ūdenstilpes nolikumu')}<p>Kartes saite ir orientieris. Tā neapstiprina privātas zemes šķērsošanu, brīvu stāvvietu vai atļautu makšķerēšanu konkrētajā punktā.</p></details></div></article>)
    end.join
    opts=DATA['fish'].map{|f|%(<option value="#{f['id']}">#{h(f['name'])}</option>)}.join
    wopts=DATA['waters'].map{|w|%(<option value="#{w['id']}">#{h(w['name'])}</option>)}.join
    yearopts=(2026..2030).map{|y|%(<option#{y==2027 ? ' selected' : ''}>#{y}</option>)}.join
    %(<article class="benefit-guide fishing-guide">
    <header class="fish-hero"><div class="fish-hero-copy"><span class="fish-kicker">LATVIJA · COPE AR SKAIDRU PLĀNU</span><h1>Copes kalendārs.<br>Vispirms datums.<br>Tad īstā vieta.</h1><p>Kad beidzas līdaku liegums? Kur vajadzīga licence? Plāno makšķerēšanu ar pārbaudāmiem sezonu datumiem, īstām zivju fotogrāfijām un Latvijas ūdenstilpju ceļvedi.</p><div class="fish-actions"><a class="benefit-button" href="#copes-parbaude">Pārbaudīt copes datumu #{GuideUI.icon('calendar')}</a><a href="#kur-makskeret">Atrast vietu #{GuideUI.icon('arrow')}</a></div><small>Pārbaudīts 16.11.2026. · MK noteikumi Nr. 800 un vietējie nolikumi</small></div>#{photo('usma',hero:true)}</header>
    <nav class="fish-subnav" aria-label="Copes ceļveža sadaļas"><a href="#copes-parbaude">Datuma pārbaude</a><a href="#liegumu-kalendars">Liegumu kalendārs</a><a href="#zivju-sugas">Zivju sugas</a><a href="#kur-makskeret">Kur makšķerēt</a><a href="#licences">Kartes un licences</a><a href="#juras-cope">Jūras cope</a></nav>
    <section id="copes-parbaude" class="fish-section fish-check-section"><div class="fish-section-title"><div><span class="fish-kicker">PIRMS DODIES PIE ŪDENS</span><h2>Vai izvēlētajā datumā ir liegums?</h2></div><p>Rīks pārbauda valsts sugas paturēšanas liegumu un norāda būtiskākos izvēlētā ezera nosacījumus. Tas neaizstāj licences nolikumu un teritorijas karti.</p></div><div class="fish-check-grid"><form data-fish-check><label>Copes datums<input type="date" name="date" min="2026-01-01" max="2030-12-31" value="2027-05-01" required></label><label>Zivju suga<select name="species">#{opts}</select></label><label>Ūdenstilpe<select name="water"><option value="general">Valsts pamatnoteikumi</option>#{wopts}</select></label><button type="submit" class="benefit-button">Pārbaudīt nosacījumus #{GuideUI.icon('arrow')}</button><p class="fish-small">Tavs datums netiek sūtīts uz serveri un netiek saglabāts. 2027.–2030. gadam rāda plānu pēc šobrīd spēkā esošās kārtības, nevis apstiprinātus nākotnes noteikumus.</p></form><div data-fish-result class="fish-check-result" aria-live="polite"><span class="fish-kicker">IZVĒLIES DATUMU</span><h3>Līdaku paturēšanas liegums beidzas 30. aprīlī.</h3><p>No 1. maija valsts sugas liegums vairs nav spēkā. Konkrēta ezera licence un laivu sezona var noteikt citus nosacījumus.</p></div></div></section>
    <section id="liegumu-kalendars" class="fish-section"><div class="fish-section-title"><div><span class="fish-kicker">KAD SĀKAS UN BEIDZAS LIEGUMI?</span><h2>Sezonu kalendārs 2026–2030</h2></div><p>Bordo josla apzīmē liegumu, gaišā daļa laiku ārpus šī konkrētā lieguma. Arī gaišajos periodos jāievēro vietējie noteikumi, minimālais garums un licences.</p></div><div class="fish-key"><span><i></i>Lieguma periods (abas robeždatumu dienas ieskaitot)</span><span>Valsts pamatnoteikumi · vietējās zonas pārbaudi atsevišķi</span></div><div class="fish-timeline-scroll" tabindex="0" role="region" aria-label="Sugu liegumu gada tabula"><table class="fish-timeline"><thead><tr><th scope="col">Suga vai paņēmiens</th><th scope="col"><span class="fish-months">#{%w[Jan Feb Mar Apr Mai Jūn Jūl Aug Sep Okt Nov Dec].map{|m|"<span>#{m}</span>"}.join}</span></th><th scope="col">Precīzais periods</th></tr></thead><tbody>#{rows}</tbody></table></div><div class="fish-export-row"><label>Atgādinājumu gads<select data-fish-year>#{yearopts}</select></label><button type="button" class="benefit-button" data-fish-export>Saglabāt liegumus kalendārā #{GuideUI.icon('download')}</button><p class="fish-small">ICS: lieguma sākuma un pirmās dienas pēc tā atgādinājumi. Vietējie izņēmumi failā nav pilnībā aptverti. Tas pats neatjaunojas; pirms copes pārbaudi avotu.</p></div><p data-fish-export-status role="status"></p><div class="fish-opening-grid"><article><span>01.05.</span><h3>Līdakas un valsts laivu pamatliegums</h3><p>Pirmā diena pēc 1. marta–30. aprīļa lieguma. Alūksnes laivu makšķerēšana sākas tikai 10. maijā.</p></article><article><span>01.06.</span><h3>Zandartu paturēšana</h3><p>Pirmā diena pēc 16. aprīļa–31. maija lieguma. Nārsta zonas ezerā var būt slēgtas ilgāk.</p></article><article><span>01.12.</span><h3>Strauta foreļu valsts lieguma beigas</h3><p>Novembra pēdējā diena vēl ir lieguma diena. Atsevišķu upju posmu noteikumus tas neatceļ.</p></article></div></section>
    <section id="zivju-sugas" class="fish-section"><div class="fish-section-title"><div><span class="fish-kicker">ĪSTAS FOTOGRĀFIJAS · SKAIDRI LIMITI</span><h2>Atpazīsti zivi, pārbaudi lomu</h2></div><p>Fotogrāfijas palīdz orientēties, bet sarežģītu sugu noteikšanai salīdzini arī oficiālā pielikuma pazīmes. Garumu mēra no purna gala līdz astes spuras galam. Skaits un svars ir vienai personai.</p></div><div class="fish-species-grid">#{cards}</div><p class="fish-small">Fotogrāfijas ir sugu ilustrācijas; tās nav apgalvojums par lomu norādītajā Latvijas ezerā. Autori, licences un pārveidojumi norādīti <a href="/pilsetas-un-fotografijas/#copes-foto">attēlu licenču sadaļā</a>. Plaudim un raudai nav atsevišķa nacionāla minimālā garuma, bet vietējais nolikums var būt stingrāks.</p></section>
    <section id="kur-makskeret" class="fish-section"><div class="fish-section-title"><div><span class="fish-kicker">IZVĒLIES BRAUCIENA VIRZIENU</span><h2>Kur makšķerēt Latvijā?</h2></div><p>Seši ezeri ar pārbaudāmiem pārvaldītājiem un licencēšanas noteikumiem. Šeit nav solītu “slepeno loma punktu”: piekļuve, ūdens līmenis un zivju aktivitāte mainās.</p></div><div class="fish-place-grid">#{waters}</div><div class="fish-callout"><h3>Babītes ezers un citas aizsargājamās teritorijas</h3><p>Valsts pavasara lieguma beigas neatver visu ezeru. Babītes ezerā ir sezonāli slēgtas zonas, īpaša laivošanas kārtība un motoru ierobežojumi. Pirms maršruta izvēles pārbaudi teritorijas karti un DAP aktuālo paziņojumu. Tas pats attiecas uz Moricsalu Usmā un Liepājas ezera aizsardzības zonām.</p>#{source('nature','Pārbaudīt DAP sezonālos liegumus')}</div></section>
    <section id="licences" class="fish-section"><div class="fish-section-title"><div><span class="fish-kicker">DIVI ATŠĶIRĪGI DOKUMENTI</span><h2>Makšķerēšanas karte un vietējā licence</h2></div><p>Valsts karte pati par sevi nedod tiesības copēt ikvienā licencētā ezerā. Arī bezmaksas vietējā licence vispirms jāsaņem.</p></div><div class="fish-permit-grid"><article><span class="fish-permit-symbol">LV</span><h3>Valsts makšķerēšanas karte</h3><p>2026. gada publicētajā piedāvājumā: dienas karte 1,50 €, mēneša 5 €, trīs mēnešu 7,50 €. Pirms pirkuma pārbaudi izvēlētās kartes derīguma periodu; tas nepāriet neierobežoti nākamajā gadā.</p><p>Karte nav vajadzīga personām, kuras ir jaunākas par 16 gadiem, vecākas par 65 gadiem, un personām ar invaliditāti. Līdzi jābūt dokumentam, ar kuru var pārbaudīt attiecīgo statusu.</p>#{source('card','Iegādāties valsts karti')}</article><article><span class="fish-permit-symbol">+</span><h3>Ūdenstilpes licence</h3><p>Licencētā vietā izvēlies konkrētā ezera vai upes posma licenci, īsto dienu un atļauto paņēmienu. Maija līdaku licence var atšķirties no parastās dienas licences. Pārbaudi pirkuma apkalpošanas maksu.</p><p>Valsts kartes atbrīvojums automātiski neatbrīvo no vietējās licences. Saglabā licenci tā, lai to varētu uzrādīt arī pie vāja sakaru pārklājuma.</p>#{source('licences','Atrast ūdenstilpes licenci')}</article></div><div class="fish-steps"><article><b>1</b><h3>Pirms pirkuma</h3><p>Pārbaudi sugu, datumu, vietas karti un to, vai drīksti izmantot laivu, velcēt vai lietot izvēlēto ēsmu.</p></article><article><b>2</b><h3>Pirms izbraukšanas</h3><p>Paņem personu apliecinošu dokumentu, licenci, lineālu, uztveramo tīkliņu un zivju saudzīgai atlaišanai vajadzīgo inventāru.</p></article><article><b>3</b><h3>Pēc copes</h3><p>Iesniedz vietējās licences lomu atskaiti tās termiņā, arī ja prasīta nulles atskaite. Burtniekā piecu dienu laikā pēc licences beigām.</p></article></div></section>
    <section id="juras-cope" class="fish-section fish-sea"><span class="fish-kicker">BALTIJAS JŪRA UN RĪGAS LĪCIS</span><h2>Jūras copei ir atsevišķi noteikumi</h2><div class="fish-sea-grid"><article><strong>Menca</strong><h3>2026. gadā nepatur</h3><p>Latvijas piekrastē mencu ieguve atpūtas zvejā ir aizliegta. Nejauši noķertu mencu atlaiž. Vecajā valsts pamatlimita tabulā redzamais skaits neatceļ aktuālo gada aizliegumu.</p></article><article><strong>Lasis</strong><h3>Tikai ar noteiktām pazīmēm</h3><p>2026. gadā jūrā drīkst paturēt vienu audzētavas lasi ar nogrieztu taukspuru; pēc pirmā šāda laša noķeršanas laša ieguvi tai dienā pārtrauc. Savvaļas lasi nekavējoties atlaiž. Valsts sezonālais laša un taimiņa paturēšanas liegums jūrā ir 1. oktobris–15. novembris; noteikumos aprakstītajai Rīgas līča joslai no Vecāķiem līdz Vaivariem ir izņēmums. Arī tur jāievēro 2026. gada laša papildu nosacījumi.</p></article><article><strong>Lomu reģistrācija</strong><h3>Arī par atlaistām zivīm</h3><p>No 10.01.2026. jāreģistrē iepriekšējās 24 stundās piekrastē noķertais zutis, menca, lasis, reņģe, brētliņa un zeltplekste, arī ja atlaista. Jūras zutis ir aizliegts loms. Reģistrācija nepadara aizliegtu ieguvi atļautu.</p></article></div><div class="fish-actions">#{source('sea2026','Lasīt 2026. gada jūras regulējumu')}#{source('sea-log','Reģistrēt jūras lomu')}</div><p class="fish-small">2027.–2030. gada mencu un lašu gada nosacījumus nevar pieņemt par identiskiem 2026. gadam. Tos pārbaudi ZM jaunākajā lēmumā. Lasis un taimiņš nav viens un tas pats; 2026. gada laša papildu ierobežojums neaizstāj taimiņa noteikumus.</p></section>
    <section class="fish-section"><div class="fish-section-title"><div><span class="fish-kicker">PRAKTISKI PIE ŪDENS</span><h2>Krasts, inventārs un saudzīgs loms</h2></div><p>Labs copes plāns ietver arī nokļūšanu krastā, drošu atgriešanos un vietas sakopšanu.</p></div><div class="fish-practical-grid"><article><h3>Piekļuve nav stāvvieta</h3><p>Tauvas josla nav atļauja braukt ar auto pāri svešai zemei, kurināt uguni vai uzstādīt nometni. Privātā ezerā, kur zvejas tiesības nepieder valstij, vajadzīga īpašnieka atļauja. Ievēro norādes, vārtus un dabas teritoriju režīmu.</p>#{source('access','Lasīt piekļuves tiesību pamatu')}</article><article><h3>Pārbaudi rīkus un vietu</h3><p>Iekšējos ūdeņos pamatā lieto līdz diviem makšķerēšanas rīkiem. Āķiem, mākslīgām ēsmām un atsevišķiem paņēmieniem ir papildu prasības. Nedrīkst makšķerēt no tiltiem vai zem to konstrukcijām; jāievēro attālumi no dambjiem, zivju ceļiem un marķētiem zvejas rīkiem.</p>#{source('rules','Lasīt rīku un vietu ierobežojumus')}</article><article><h3>Atlaišana bez liekas kavēšanās</h3><p>Sagatavo tīkliņu un atāķēšanas knaibles pirms zivs izcelšanas. Zemizmēra vai aizliegtu zivi saudzīgi atbrīvo un nekavējoties atlaiž. Ja āķi nevar saudzīgi izņemt, noteikumi paredz nogriezt auklu un atlaist zivi ar āķi.</p>#{source('rules','Skatīt 21. punktu')}</article><article><h3>Ūdens un ledus drošība</h3><p>No krasta pārbaudi laika apstākļus, bet laivā lieto piemērotu glābšanas vesti un par maršrutu pasaki tuviniekam. Kalendārs neapstiprina ledus nestspēju. Vietējais aizliegums kāpt uz ledus jāievēro neatkarīgi no tā, vai citi jau makšķerē.</p>#{source('safety','VUGD norādījumi drošībai')}</article></div></section>
    <section class="fish-section fish-faq"><span class="fish-kicker">ATBILDES PIRMS COPES</span><h2>Bieži uzdotie jautājumi</h2><details><summary>Kad 2027. gadā beidzas līdaku liegums?</summary><p>Pēc šobrīd spēkā esošajiem valsts pamatnoteikumiem pēdējā lieguma diena ir 30. aprīlis, un pirmā diena pēc lieguma ir 1. maijs. Tā nav garantija, ka jebkurā ezerā drīkst doties ar laivu vai paturēt līdaku bez īpašās licences. Pirms brauciena pārbaudi, vai noteikumi nav mainīti.</p></details><details><summary>Kad atveras zandartu sezona?</summary><p>Valsts zandartu paturēšanas liegums ir no 16. aprīļa līdz 31. maijam ieskaitot. Pirmā diena pēc tā ir 1. jūnijs. Ezeru atsevišķas nārsta vietas var būt slēgtas ilgāk, piemēram, Burtnieka norādītās vietas līdz 15. jūnijam.</p></details><details><summary>Vai aizliegums paturēt zivi nozīmē pilnīgu makšķerēšanas aizliegumu?</summary><p>Nē, tie ir atšķirīgi nosacījumi. Paturēšanas liegumā attiecīgo zivi nedrīkst saglabāt lomā. Citviet konkrētā laikā ir aizliegta pati makšķerēšana, uzturēšanās, laivošana vai paņēmiens. “Noķer un atlaid” principu nevar izmantot, lai apietu makšķerēšanas vai teritorijas liegumu.</p></details><details><summary>Vai asarus un raudas var ķert visu gadu?</summary><p>Tām nav atsevišķa valsts sugas paturēšanas lieguma, taču tas nenozīmē brīvu makšķerēšanu jebkurā vietā. Pavasarī ir laivu un kanālu liegumi, bet ezeros vietējās zonas, licences un loma limiti.</p></details><details><summary>Vai šis ir Mēness fāžu copes prognožu kalendārs?</summary><p>Nē. Šeit sezonu pamats ir pārbaudāmi noteikumi. Lomu ietekmē arī ūdens temperatūra, skābeklis, vējš, caurspīdīgums, vieta un izvēlētais paņēmiens. Mēness fāze pati par sevi negarantē zivju aktivitāti vai labu lomu.</p></details><details><summary>Vai 2028., 2029. un 2030. gada datumi jau ir oficiāli apstiprināti?</summary><p>Rīks atkārto pašreizējo valsts noteikumu mēneša un dienas robežas plānošanai. Nākotnes grozījumi, gada jūras lēmumi un vietējo licenču izmaiņas var to mainīt. Tāpēc katram nākotnes datumam ir pārbaudes norāde, un ICS nav pastāvīgs oficiālo noteikumu abonements.</p></details></section>
    <nav class="fish-related" aria-label="Citi dabas plānošanas rīki"><a href="/saullekts-saulriets/">Saullēkts un saulriets #{GuideUI.icon('arrow')}</a><a href="/meness-kalendars/">Mēness fāzes #{GuideUI.icon('arrow')}</a><a href="/dienu-skaititajs/">Dienas līdz braucienam #{GuideUI.icon('arrow')}</a></nav></article><script type="application/json" id="fish-guide-data">#{JSON.generate(DATA.slice('fish','closures','waters','checkedAt')).gsub('<','\\u003c')}</script>)
  end
  def notes
    {'heading'=>'Copes datums jāsalīdzina ar vietu un paņēmienu','paragraphs'=>['Valsts sugas liegums, vietējā licence un dabas teritorijas režīms ir atšķirīgi nosacījumi. Lomu plāno tikai tad, kad pārbaudīti visi trīs.','Kalendārs rāda konkrēta aizlieguma robežas, nevis paredz zivju aktivitāti. Nākotnes datumos pirms brauciena jāpārbauda noteikumu grozījumi. Izvēlies arī konkrēto ūdenstilpi un iepazīsties ar piekļuves nosacījumiem, jo valsts noteikumi vien neatbild uz visiem jautājumiem.'],'icon'=>'calendar','sources'=>DATA['sources'].first(2),'related'=>[{'url'=>'/saullekts-saulriets/','title'=>'Saules laiki pie ūdens'}]}
  end
end
